(() => {
  const $ = selector => document.querySelector(selector);
  const typeNames = {person:'真人',robot:'机器人',dog:'机器狗',drone:'无人机'};
  const typeIcons = {robot:'/assets/icons/robot.png',dog:'/assets/icons/robot-dog.png',drone:'/assets/icons/drone.png',person:'/assets/icons/person.png'};
  const markIcons = {alert:'/assets/icons/alert.png',patrol:'/assets/icons/patrol.png'};
  const taskTypeFor = {person:'team',robot:'robot',dog:'robot',drone:'drone'};
  const taskTypeNames = {team:'人工巡检',robot:'机器人巡检',drone:'无人机巡检'};
  const pageTitles = {dashboard:'总览',devices:'设备',tasks:'任务',dispatch:'调度',settings:'系统'};
  const e = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const consoleIcon = name => `<svg class="console-icon" aria-hidden="true"><use href="/assets/icons/console-sprite.svg#${name}"></use></svg>`;
  let eventType='', page='dispatch', dashboardDeviceType='all', selectedTask=null, tasks=[], resources=[], feedback=[], alarms=[], simulationEvents=[], terrainPredictions=[], incidents=[], devices=[], environment={}, telemetryContract={}, toastTimer, aiPlan=null, previewPlan=null, v1Plan=null, openingSchemes=null, selectedPlanIndex=0, batteryTimer=null;
  const openSchemes=new Set();
  const getStore=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key)||JSON.stringify(fallback));}catch{return fallback;}};
  const saveStore=(key,value)=>localStorage.setItem(key,JSON.stringify(value));
  let overviewType='person';
  function overviewDevices(){const idle=resources.filter(item=>['待命','在线'].includes(item.status));return `<div class="resource-counts">${Object.entries(typeNames).map(([type,label])=>`<button type="button" class="resource-count${overviewType===type?' active':''}" data-overview-type="${type}" aria-pressed="${overviewType===type}"><span>${label}</span><b>${idle.filter(item=>item.type===type).length}</b></button>`).join('')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>设备名称</th><th>类型</th><th>通信方式</th><th>状态</th></tr></thead><tbody>${resources.filter(item=>item.type===overviewType).map(item=>`<tr><td><strong>${e(item.name)}</strong></td><td>${typePill(item.type)}</td><td>${e(item.protocol||'统一接入')}</td><td>${badge(item.status)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty-state">暂无设备</td></tr>'}</tbody></table></div>`;}
  function updateOverviewDevices(){const body=$('.dashboard-grid .card:first-child .card-body');if(!body)return;body.innerHTML=overviewDevices();body.querySelectorAll('[data-overview-type]').forEach(button=>button.onclick=()=>{overviewType=button.dataset.overviewType;updateOverviewDevices();});}
  function toast(message){const node=$('#toast');node.textContent=message;node.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('show'),2300)}
  window.toast=toast;
  function applyTheme(theme){const next=theme==='dark'?'dark':'light';document.documentElement.dataset.theme=next;saveStore('uav_theme_console',next);const button=$('#themeToggle');if(button){button.innerHTML=consoleIcon(next==='dark'?'sun':'moon');button.setAttribute('aria-label',next==='dark'?'切换浅色模式':'切换深色模式');button.title=button.getAttribute('aria-label');}}
  function initTheme(){applyTheme(getStore('uav_theme_console','dark'));const button=$('#themeToggle');if(button)button.onclick=()=>applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');}
  async function api(url,options={}){const response=await fetch(url,{cache:'no-store',...options});const body=await response.json();if(!response.ok)throw new Error(body.error||'请求失败');return body;}
  async function refreshData(){
    try{
      if(!refreshData.booted){
        refreshData.booted=true;
        const overrides=getStore('uav_task_overrides',{});
        Object.values(overrides).forEach(item=>{if(item&&typeof item==='object')for(const key of ['executor','status','dispatch_started_at','simulation_duration_seconds','progress'])delete item[key];});
        saveStore('uav_task_overrides',overrides);
        const demo=await api('/api/simulation/demo',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});
        openingSchemes=demo.schemes||[];
      }
      const [taskData,overview,feedbackData,planData]=await Promise.all([api('/api/tasks'),api('/api/overview'),api('/api/feedback'),api('/api/planning/plan')]);
      previewPlan=planData;
      v1Plan=planData;
      const overrides=getStore('uav_task_overrides',{});
      tasks=taskData.map(task=>({...task,...(overrides[task.id]||{})}));
      resources=[...(overview.resources||[]),...getStore('uav_extra_devices',[])];
      terrainPredictions=overview.terrain_predictions||[];simulationEvents=overview.simulation_events||[];feedback=feedbackData||[];alarms=overview.alarms||[];incidents=overview.incidents||[];environment=overview.environment||{};telemetryContract=overview.telemetry_contract||{};
      render();
    }catch(error){$('#pageContent').innerHTML=`<div class="card empty-state">${e(error.message)}。请确认 Python 服务已启动。</div>`;}
  }
  function setPage(next){if(next==='monitor')next='dispatch';page=next;if(next==='dispatch'&&!v1Plan)v1Plan=previewPlan;selectedTask=null;document.querySelectorAll('.nav-link').forEach(item=>item.classList.toggle('active',item.dataset.page===page));$('#pageTitle').textContent=pageTitles[page];render();}
  function badge(status){const cls=['在线','待命','已完成','完成'].includes(status)?'online':['执行中','已派发','作业中'].includes(status)?'busy':['异常','离线','返厂中','待检修'].includes(status)?'warn':'off';return `<span class="status-pill ${cls}">${e(status||'待调度')}</span>`;}
  function metric(label,value){return `<div class="card metric"><div class="metric-label">${label}</div><div class="metric-value">${value}</div></div>`;}
  function deviceIcon(type,kind=''){const src=typeIcons[type];return src?`<span class="device-icon ${kind}"><img src="${src}" alt="" aria-hidden="true"></span>`:'';}
  function streetLabel(item){const p=item.position||{},x=Number(p.x)||50,y=Number(p.y)||50;if(x<45)return '文泽路 · 西段';if(y<40)return '金沙湖路 · 南侧';if(x>58)return '2 号大街 · 东段';if(y>57)return '学源街 · 北段';return '高教园区主路 · 中段';}
  function urgentTask(task){return !!(task&&(String(task.name||'').startsWith('紧急')||task.interruption));}
  function taskMark(task){const urgent=urgentTask(task);return `<img class="mark-icon ${urgent?'alert':'patrol'}" src="${urgent?markIcons.alert:markIcons.patrol}" alt="" aria-hidden="true">`;}
  function linkedTask(resource){return tasks.find(task=>task.name===resource.task)||tasks.find(task=>['执行中','已派发','返厂中'].includes(task.status)&&String(task.executor||'').split('、').includes(resource.name));}
  function teamChips(group){return group.map(item=>`${deviceIcon(item.resource_type,'compact')}<b>${e(item.resource_name)}</b>`).join('');}
  function namedDeviceMarks(text){return String(text||'').split(/[、,，]/).map(part=>part.trim()).filter(Boolean).map(part=>{const clean=part.replace(/^替补：/,'');const resource=resources.find(item=>clean.includes(item.name));return `${resource?deviceIcon(resource.type,'compact'):''}<span>${e(part)}</span>`;}).join('');}
  function typePill(type){return `<span class="type-pill">${deviceIcon(type,'compact')}${e(typeNames[type]||typeNames.person)}</span>`;}
  function actionButton(label,action,kind=''){const icon={"add-device":"plus","add-task":"plus","create-emergency":"plus","simulate-incident":"alert","send-task":"send"}[action];return `<button class="btn ${kind}" data-action="${action}">${icon?consoleIcon(icon):''}<span>${label}</span></button>`;}
  const capabilityNames={manual_inspection:'人工复核',rgb_camera:'可见光',thermal:'热成像',gas:'气体检测',lidar:'激光雷达',aerial_camera:'航拍'};
  function batteryCell(item){if(item.power_percent==null)return '<span class="telemetry-na">—</span>';const value=Number(item.power_percent);if(!Number.isFinite(value))return '<span class="telemetry-na">—</span>';const tone=value<35?'critical':value<60?'warn':'good';return `<div class="battery-readout ${tone}" data-battery="${value}" data-running="${['执行中','已派发','作业中'].includes(item.status)?'1':'0'}"><b>${value}%</b><div class="battery-track"><i style="width:${value}%"></i></div></div>`;}
  function weatherStrip(){const weather=environment.weather||{};return `<section class="weather-rail"><b>${e(weather.condition||'天气')}</b><span>${e(weather.temperature_c??'—')}°C</span><span>风 ${e(weather.wind_mps??'—')} m/s</span><span>能见度 ${e(weather.visibility_km??'—')} km</span><span class="${environment.flight_allowed?'safe-text':'danger-text'}">${environment.flight_allowed?'可飞':'停飞'}</span></section>`;}
  function startBatteryAnimation(){/* Numeric telemetry comes from /api/overview; CSS animates the bar. */}

  function render(){
    const actions=$('#pageActions');actions.className='page-actions';
    if(page==='dashboard'){actions.innerHTML=actionButton('＋ 新建设备','add-device')+actionButton('＋ 新建任务','add-task','primary');$('#pageContent').innerHTML=dashboardView();}
    if(page==='devices'){actions.innerHTML=actionButton('＋ 新增设备','add-device','primary');$('#pageContent').innerHTML=deviceV1View();}
    if(page==='tasks'){actions.innerHTML=actionButton('＋ 创建任务','add-task','primary');$('#pageContent').innerHTML=taskView();}
    if(page==='dispatch'){actions.innerHTML=`<select id="eventType" class="select" aria-label="事件类型">${[['','随机事件'],['robot','地面巡检'],['drone','空中巡检']].map(([value,label])=>`<option value="${value}" ${eventType===value?'selected':''}>${label}</option>`).join('')}</select>`+actionButton('故障上报','simulate-incident')+actionButton('新增事件','create-emergency','primary');$('#pageContent').innerHTML=dispatchV1View();}
    if(page==='settings'){actions.innerHTML='';$('#pageContent').innerHTML=settingsView();}
    if(['dashboard','dispatch'].includes(page))initSpatialScene();
    bindActions();
    startBatteryAnimation();
    updateCostNumbers();
    tickLiveBoard();
  }
  function dashboardView(){
    const idle=resources.filter(item=>['待命','在线'].includes(item.status));
    const done=tasks.filter(item=>item.status==='已完成').length;
    const pending=tasks.filter(item=>['待调度','待派发'].includes(item.status)).length;
    const dashboardRows=dashboardDeviceType==='all'?Object.keys(typeNames).flatMap(type=>resources.filter(item=>item.type===type).slice(0,2)).slice(0,8):resources.filter(item=>item.type===dashboardDeviceType).slice(0,8);
    return `${weatherStrip()}<div class="metric-grid">${metric('设备',resources.length)}${metric('空闲',idle.length)}${metric('任务',tasks.length)}${metric('待调度',pending)}</div>
      <div class="dashboard-grid"><section class="card"><div class="card-head"><h2>设备</h2><span class="hint">点击类型筛选</span><button class="btn right" data-action="navigate-devices">全部</button></div><div class="card-body"><div class="resource-counts">${Object.entries(typeNames).map(([type,label])=>`<button type="button" class="resource-count ${dashboardDeviceType===type?'selected':''}" data-action="dashboard-device-filter" data-type="${type}" aria-pressed="${dashboardDeviceType===type}">${deviceIcon(type)}<span><label>${label}</label><b>${idle.filter(item=>item.type===type).length}</b></span></button>`).join('')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>名称</th><th>类型</th><th>通信</th><th>状态</th></tr></thead><tbody>${dashboardRows.map(item=>`<tr><td><strong>${e(item.name)}</strong></td><td>${typePill(item.type)}</td><td>${e(item.protocol||'—')}</td><td>${badge(item.status)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty-state">没有该类型设备</td></tr>'}</tbody></table></div></div></section>
      <section class="card"><div class="card-head"><h2>任务</h2><button class="btn right" data-action="navigate-tasks">全部</button></div><div class="card-body task-list">${tasks.slice(0,6).map(taskItem).join('')||'<div class="empty-state">暂无任务</div>'}</div></section>
      <section class="card"><div class="card-head"><h2>设备回传</h2><span class="hint">仿真遥测</span></div><div class="card-body">${(feedback.length?feedback:robotFeedback()).slice(0,3).map(item=>feedbackItem(item)).join('')}</div></section>
      <section class="card"><div class="card-head"><h2>下沙</h2></div>${spatialMarkup()}</section></div>`;
  }
  function taskItem(task){return `<div class="task-item" data-task="${e(task.id)}"><div><div class="task-name">${e(task.name)}</div></div>${badge(task.status)}</div>`;}
  function robotFeedback(){return [{device:'领航者 NAVIAI-WA2 · 02',task_name:'学源街路面巡检',kind:'视觉告警',message:'发现路面纵向裂缝，建议纳入复核路线。',time:'刚刚',confidence:'0.93',image:'/assets/defects/road-damage.jpg',source:'公开缺陷样例'}, {device:'多旋翼巡检机 · 02',task_name:'高空设施复核',kind:'完成回传',message:'屋顶设备外观正常，已上传 3 个检查点图像。',time:'2 分钟前',confidence:'0.88',image:'/assets/defects/example-2.png',source:'公开缺陷样例'}, {device:'四足巡检单元 · 03',task_name:'安全通道复核',kind:'通行回传',message:'碎石坡通行概率下降，路线代价已上调。',time:'5 分钟前',confidence:'0.76',source:'仿真遥测'}];}
  function feedbackItem(item){return `<div class="feedback-row robot-feedback"><i class="feedback-sev ${item.kind==='完成回传'?'done':''}"></i>${item.image?`<img src="${e(item.image)}" alt="${e(item.source||'现场图')}" loading="lazy">`:''}<div><div class="feedback-title">${e(item.device||'设备')} · ${e(item.kind||'运行回传')}</div><div class="feedback-text">${e(item.message||item.description||'')}</div><small class="feedback-meta">${item.confidence?`置信度 ${e(item.confidence)} · `:''}${e(item.source||'仿真遥测')}</small></div><time class="feedback-time">${e(item.time||'')}</time></div>`;}
  function mapDots(items){return items.map((item,index)=>{const x=8+(index*19)%84,y=15+(index*31)%70;const cls=['待命','在线'].includes(item.status)?'':'busy';return `<i class="map-dot ${cls}" style="left:${x}%;top:${y}%" title="${e(item.name)} · ${e(item.status)}"></i><span class="map-label" style="left:${x}%;top:${y}%">${e(item.name)}</span>`}).join('');}
  let spatialScene=null;
  function legendItems(){const rows=[['robot','#426d89','机器人',typeIcons.robot],['dog','#836044','机器狗',typeIcons.dog],['drone','#306caa','无人机',typeIcons.drone],['person','#667967','巡检员',typeIcons.person],['alert','#c55b4b','紧急',markIcons.alert]];return rows.map(([key,color,label,src])=>`<span class="legend-${key}" style="color:${color}"><img class="glyph" src="${src}" alt="">${label}</span>`).join('')+'<span class="legend-route" style="color:#168762"><i class="legend-line"></i>规划路线</span>';}
  function spatialMarkup(){const legend=legendItems();return `<div class="simulation-space"><div class="space-toolbar"><div class="space-modes"><button class="active" data-view-3d>${consoleIcon('map')}<span>路网</span></button><button data-view-satellite>${consoleIcon('satellite')}<span>卫星</span></button></div><span data-space-count></span><label>设备 <select data-device-select aria-label="选中设备"></select></label><button class="btn map-zoom" data-zoom-in aria-label="放大地图" title="放大地图">${consoleIcon('zoomIn')}</button><button class="btn map-zoom" data-zoom-out aria-label="缩小地图" title="缩小地图">${consoleIcon('zoomOut')}</button><button class="btn" data-lock-device>${consoleIcon('lock')}<span class="console-button-label">锁定设备</span></button><button class="btn" data-show-all>${consoleIcon('layers')}<span class="console-button-label">全部</span></button><button class="btn" data-view-reset>${consoleIcon('reset')}<span>复位</span></button></div><div class="space-viewport"><div class="space-map"><canvas aria-label="下沙路网" tabindex="0"></canvas><div class="scene-legend">${legend}</div></div><aside class="altitude-axis" aria-label="设备海拔"><div class="altitude-title">海拔</div><div class="altitude-body"><div class="altitude-scale" data-altitude-scale></div><div class="altitude-list" data-altitude-list></div></div></aside></div><div class="space-readout" data-device-readout></div><div class="space-foot"><span data-osm-credit>© OpenStreetMap contributors</span></div></div>`;}
  function initSpatialScene(){const placeholder=$('.simulation-space');if(!placeholder||!window.SpatialScene)return;if(spatialScene){if(placeholder!==spatialScene.host)placeholder.replaceWith(spatialScene.host);}else spatialScene=new SpatialScene(placeholder);const plan=v1Plan||previewPlan;spatialScene.update({resources,tasks,incidents,terrain:terrainPredictions,plan,selectedTaskId:plan?.assignments?.[selectedPlanIndex]?.task_id});}

  function deviceView(){
    const type=$('#deviceTypeFilter')?.value||'all',status=$('#deviceStatusFilter')?.value||'all',query=($('#deviceSearch')?.value||'').toLowerCase();
    const list=resources.filter(item=>(type==='all'||item.type===type)&&(status==='all'||item.status===status)&&`${item.name} ${item.id}`.toLowerCase().includes(query));
    return `<div class="card"><div class="toolbar"><input class="input" id="deviceSearch" placeholder="搜索设备名称或编号" value="${e(query)}"><select class="select" id="deviceTypeFilter"><option value="all">全部类型</option>${Object.entries(typeNames).map(([key,value])=>`<option value="${key}" ${type===key?'selected':''}>${value}</option>`).join('')}</select><select class="select" id="deviceStatusFilter"><option value="all">全部状态</option>${['待命','执行中','在线','离线','异常'].map(x=>`<option ${status===x?'selected':''}>${x}</option>`).join('')}</select><span class="spacer"></span><span class="hint">共 ${list.length} 台</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>设备名称 / 编号</th><th>设备类型</th><th>厂商型号</th><th>通信协议</th><th>接入方式</th><th>在线状态</th><th>当前任务</th><th>操作</th></tr></thead><tbody>${list.map(item=>`<tr><td><strong>${e(item.name)}</strong><div class="task-meta">${e(item.id)}</div></td><td>${typePill(item.type)}</td><td>${e(item.vendor||'—')}</td><td>${e(item.protocol||'HTTP/MQTT')}</td><td>${e(item.access||'边缘网关')}</td><td>${badge(item.status)}</td><td>${e(item.task||'—')}</td><td><button class="btn" data-action="device-detail" data-id="${e(item.id)}">详情</button> <button class="btn" data-action="device-edit" data-id="${e(item.id)}">编辑</button></td></tr>`).join('')||'<tr><td colspan="8" class="empty-state">没有匹配的设备</td></tr>'}</tbody></table></div></div>`;
  }
  function deviceV1View(){
    const type=$('#deviceTypeFilter')?.value||'all',status=$('#deviceStatusFilter')?.value||'all',query=($('#deviceSearch')?.value||'').toLowerCase();
    const list=resources.filter(item=>(type==='all'||item.type===type)&&(status==='all'||item.status===status)&&`${item.name} ${item.id}`.toLowerCase().includes(query));
    return `${weatherStrip()}<section class="card telemetry-card"><div class="card-head"><h2>遥测</h2></div><div class="toolbar"><input class="input" id="deviceSearch" placeholder="搜索设备名称或编号" value="${e(query)}"><select class="select" id="deviceTypeFilter"><option value="all">全部类型</option>${Object.entries(typeNames).map(([key,value])=>`<option value="${key}" ${type===key?'selected':''}>${value}</option>`).join('')}</select><select class="select" id="deviceStatusFilter"><option value="all">全部状态</option>${['待命','执行中','在线','离线','异常'].map(x=>`<option ${status===x?'selected':''}>${x}</option>`).join('')}</select><span class="spacer"></span><span class="hint">${list.length} 台/组</span></div><div class="table-wrap"><table class="data-table telemetry-table"><thead><tr><th>设备 / 状态</th><th>电量</th><th>位置</th><th>能力</th><th>通行边界</th><th>连接</th><th>操作</th></tr></thead><tbody>${list.map(item=>`<tr><td><div class="device-name-cell">${deviceIcon(item.type,item.status==='离线'?'offline':'')}<span><strong>${e(item.name)}</strong><small>${e(item.id)} · ${e(typeNames[item.type])}</small></span></div>${item.status==='离线'?'':badge(item.status)}</td><td>${batteryCell(item)}</td><td><b class="street-value">${e(streetLabel(item))}</b><small class="cell-note">坐标见详情</small></td><td><div class="capability-list">${(item.capabilities||[]).map(cap=>`<span>${e(capabilityNames[cap]||cap)}</span>`).join('')}</div></td><td><b>${e(item.max_slope_deg)}°</b><small class="cell-note">通道 ≥ ${e(item.min_width_m)} m</small></td><td><b>${e(item.signal_percent)}%</b><small class="cell-note">${e(item.last_seen_seconds)} 秒前</small></td><td><button class="btn" data-action="device-detail" data-id="${e(item.id)}">详情</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty-state">没有匹配的设备</td></tr>'}</tbody></table></div></section>`;
  }
  function taskView(){return `<div class="card"><div class="toolbar"><input class="input" id="taskSearch" placeholder="搜索任务名称" value="${e($('#taskSearch')?.value||'')}"><select class="select" id="taskStatusFilter"><option value="all">全部状态</option>${['待调度','已派发','执行中','已完成','异常','待复核'].map(x=>`<option>${x}</option>`).join('')}</select><span class="spacer"></span><span class="hint">任务 ${tasks.length} 条</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>任务名称</th><th>任务类型</th><th>关联路线</th><th>执行设备</th><th>执行进度</th><th>状态</th><th>操作</th></tr></thead><tbody>${tasks.map(task=>`<tr data-task-progress="${e(task.id)}"><td><strong>${e(task.name)}</strong></td><td>${e(taskTypeNames[task.type]||'巡检')}</td><td>${e(task.route_id||'—')}</td><td>${e(task.executor||'待分配')}</td><td>${progressMeter(task)}</td><td>${badge(task.status)}</td><td><button class="btn" data-task="${e(task.id)}">查看</button> <button class="btn" data-action="task-edit" data-id="${e(task.id)}">编辑</button></td></tr>`).join('')}</tbody></table></div></div>`;}
  function dispatchAnalysisView(){const pending=tasks.filter(task=>['\u5f85\u8c03\u5ea6','\u5f85\u6d3e\u53d1'].includes(task.status));const now=new Date().toLocaleTimeString('zh-CN',{hour12:false});return `<section class="card dispatch-analysis"><div class="card-head"><div><h2>\u8c03\u5ea6\u5206\u6790</h2><span class="hint">\u57fa\u4e8e\u5f53\u524d\u4efb\u52a1\u4e0e\u8d44\u6e90\u5feb\u7167 \u00b7 ${now}</span></div><span class="spacer"></span><span class="decision-tag">\u89c4\u5219\u5019\u9009 + \u5343\u95ee\u5efa\u8bae</span></div><div class="card-body table-wrap"><table class="data-table"><thead><tr><th>\u5f85\u8c03\u5ea6\u4efb\u52a1</th><th>\u4efb\u52a1\u80fd\u529b</th><th>\u5408\u89c4\u5019\u9009\u8bbe\u5907</th><th>\u5343\u95ee\u5efa\u8bae</th><th>\u9009\u62e9\u4f9d\u636e</th></tr></thead><tbody>${pending.map(task=>{const candidates=resources.filter(resource=>taskTypeFor[resource.type]===task.type&&['\u5f85\u547d','\u5728\u7ebf'].includes(resource.status)&&resource.station===task.station);const choice=aiPlan?.assignments?.find(item=>item.task_id===task.id);return `<tr><td><strong>${e(task.name)}</strong><div class="task-meta">${e(task.route_id||task.id)}</div></td><td>${e(taskTypeNames[task.type]||task.type)}</td><td>${candidates.length?candidates.map(resource=>`<span class="candidate-chip">${e(resource.name)} \u00b7 ${e(resource.status)}</span>`).join(' '):'<span class="analysis-empty">\u65e0\u5408\u89c4\u5019\u9009</span>'}</td><td>${choice?`<b class="ai-choice">${e(choice.resource_name)}</b>`:'\u7b49\u5f85\u751f\u6210\u5efa\u8bae'}</td><td>${choice?e(choice.reason):'\u9700\u540c\u65f6\u6ee1\u8db3\u80fd\u529b\u3001\u72b6\u6001\u548c\u573a\u7ad9\u89c4\u5219'}</td></tr>`}).join('')||'<tr><td colspan="5" class="empty-state">\u5f53\u524d\u6ca1\u6709\u5f85\u8c03\u5ea6\u4efb\u52a1</td></tr>'}</tbody></table></div><div class="decision-footnote">\u5019\u9009\u8bbe\u5907\u6309\u4efb\u52a1\u7c7b\u578b\u3001\u5728\u7ebf\u72b6\u6001\u548c\u573a\u7ad9\u5f52\u5c5e\u7b5b\u9009\u3002\u672a\u63d0\u4f9b\u53ef\u9760\u7684\u5b9e\u65f6\u8ddd\u79bb\u3001\u7535\u91cf\u6216\u8d1f\u8f7d\u6570\u636e\uff0c\u56e0\u6b64\u4e0d\u5c55\u793a\u865a\u6784\u8bc4\u5206\uff1b\u6700\u7ec8\u6d3e\u53d1\u4ecd\u7531\u670d\u52a1\u7aef\u89c4\u5219\u6821\u9a8c\u3002</div></section>`;}
  function dispatchView(){const pending=tasks.filter(item=>['待调度','待派发'].includes(item.status));const plan=aiPlan?`<section class="card ai-plan"><div class="card-head"><div><h2>千问调度建议</h2><div class="hint">模型 ${e(aiPlan.model)} · ${e(aiPlan.summary)}</div></div><span class="spacer"></span>${aiPlan.assignments.length?actionButton('确认并执行调度','apply-ai-plan','primary'):''}<button class="btn" data-action="clear-ai-plan">关闭</button></div><div class="card-body table-wrap"><table class="data-table"><thead><tr><th>任务</th><th>分配资源</th><th>调度理由</th></tr></thead><tbody>${aiPlan.assignments.map(item=>`<tr><td><strong>${e(item.task_name)}</strong></td><td>${e(item.resource_name)}</td><td>${e(item.reason)}</td></tr>`).join('')||'<tr><td colspan="3" class="empty-state">没有生成可执行的匹配方案</td></tr>'}</tbody></table>${aiPlan.unmatched_tasks?.length?`<div class="hint" style="padding:12px 0">有 ${aiPlan.unmatched_tasks.length} 项任务暂未找到合适资源。</div>`:''}</div></section>`:'';return `${dispatchAnalysisView()}${plan}<div class="two-col"><section class="card"><div class="card-head"><h2>待调度任务</h2><span class="hint">${pending.length} 项</span><span class="spacer"></span><button class="btn primary" data-action="ai-dispatch">✦ AI 生成调度方案</button></div><div class="card-body task-list">${pending.map(taskItem).join('')||'<div class="empty-state">当前没有待调度任务</div>'}</div></section><section class="card"><div class="card-head"><h2>可用执行资源</h2><span class="hint">按任务类型与资源能力匹配</span></div><div class="card-body table-wrap"><table class="data-table"><thead><tr><th>设备/人员</th><th>类别</th><th>状态</th><th>可匹配任务</th><th>操作</th></tr></thead><tbody>${resources.filter(item=>['待命','在线'].includes(item.status)).map(item=>{const matching=pending.filter(task=>task.type===taskTypeFor[item.type]);return `<tr><td><strong>${e(item.name)}</strong></td><td>${typePill(item.type)}</td><td>${badge(item.status)}</td><td>${matching.length} 项</td><td>${matching.length?actionButton('分配','dispatch-one'):''}</td></tr>`}).join('')}</tbody></table></div></section></div>`;}
  function dispatchSceneView(){return `<section class="card dispatch-scene">${spatialMarkup()}</section>`;}
  function unitProgress(resource){const motion=resource.motion;if(!motion?.started_at||!['执行中','已派发','返厂中'].includes(resource.status))return null;const elapsed=(Date.now()-Date.parse(motion.started_at))/1000;return Math.max(0,Math.min(1,elapsed/Math.max(1,Number(motion.duration_seconds)||1)));}
  function taskProgress(task){if(!task?.dispatch_started_at||!['执行中','已派发','返厂中'].includes(task.status))return null;const elapsed=(Date.now()-Date.parse(task.dispatch_started_at))/1000;return Math.max(0,Math.min(1,elapsed/Math.max(1,Number(task.simulation_duration_seconds)||1)));}
  function progressMeter(task){const ratio=taskProgress(task);const pct=ratio==null?0:Math.round(ratio*100);if(ratio==null&&!['执行中','已派发','返厂中'].includes(task.status))return e(task.progress||'—');return `<span class="progress-line"><span class="progress-ring" data-task-ring style="--progress:${pct}" aria-label="进度 ${pct}%"><span data-task-label>${pct}%</span></span></span>`;}
  function tickLiveBoard(){document.querySelectorAll('[data-motion-resource]').forEach(row=>{const resource=resources.find(item=>item.id===row.dataset.motionResource);const progress=resource?unitProgress(resource):null;if(progress==null)return;const pct=Math.round(progress*100);const bar=row.querySelector('[data-motion-bar]');const label=row.querySelector('[data-motion-label]');if(bar)bar.style.width=`${pct}%`;if(label)label.textContent=resource.status==='返厂中'?`返厂 ${pct}%`:`${pct}%`;});document.querySelectorAll('[data-task-progress]').forEach(row=>{const task=tasks.find(item=>item.id===row.dataset.taskProgress);const progress=task?taskProgress(task):null;if(progress==null)return;const pct=Math.round(progress*100);const ring=row.querySelector('[data-task-ring]');const label=row.querySelector('[data-task-label]');if(ring)ring.style.setProperty('--progress',pct);if(label)label.textContent=`${pct}%`;});}
  function schemeList(taskId){const rows=(openingSchemes||(v1Plan||previewPlan)?.schemes||[]).filter(item=>item.task_id===taskId).slice(0,3);if(!rows.length)return '';const open=openSchemes.has(taskId);return `<div class="scheme-list${open?' open':''}"><button type="button" class="scheme-toggle" data-scheme-toggle="${e(taskId)}" aria-expanded="${open}" title="仿真策略评分，非训练模型">AI 推荐<small>${rows.length}</small></button><div class="scheme-body">${rows.map((scheme,index)=>`<div class="scheme${index?'':' best'}"><em>${scheme.score}</em><b>${scheme.members.map(member=>e(member.name)).join('、')}</b><i class="ops-track"><i style="width:${Math.max(4,Math.round(scheme.score))}%"></i></i></div>`).join('')}</div></div>`;}
  function holdReason(task){const rows=((v1Plan||previewPlan)?.audit||[]).filter(row=>row.task_id===task.id&&taskTypeFor[row.resource_type]===task.type);const idle=rows.filter(row=>!(row.rejected_by||[]).some(reason=>reason==='设备非空闲或不在线'||reason==='已分配给其他任务'));const pool=idle.length?idle:rows;const counts={};pool.forEach(row=>{(row.rejected_by||[]).filter(reason=>reason!=='设备类型与任务不匹配').forEach(reason=>{counts[reason]=(counts[reason]||0)+1;});});const top=Object.entries(counts).sort((a,b)=>b[1]-a[1])[0];return top?top[0]:'没有可派设备';}
  function liveRoster(){const moving=resources.filter(item=>['执行中','已派发','返厂中'].includes(item.status));const repair=resources.filter(item=>item.status==='待检修');const idle=resources.filter(item=>['待命','在线'].includes(item.status)).length;const rows=moving.map(item=>{const progress=unitProgress(item);const pct=progress==null?0:Math.round(progress*100);const task=linkedTask(item);return `<div class="ops-row" data-motion-resource="${e(item.id)}"><button class="ops-name" data-action="focus-device" data-id="${e(item.id)}">${deviceIcon(item.type)}<span><b>${e(item.name)}</b><small>${taskMark(task)}${e(item.task||'—')}</small>${item.dispatch_note?`<small class="ops-fix">${e(item.dispatch_note)}</small>`:''}</span></button>${badge(item.status)}<i class="ops-track"><i data-motion-bar style="width:${pct}%"></i></i><em data-motion-label>${item.status==='返厂中'?`返厂 ${pct}%`:`${pct}%`}</em></div>`;}).join('');const repairLine=repair.length?`<div class="ops-repair">待检修 · ${repair.map(item=>e(item.name)).join('、')}</div>`:'';return `<section class="card ops-card"><div class="card-head"><h2>在途</h2><span class="hint">${moving.length}</span></div><div class="ops-list">${rows||'<div class="empty-state">暂无</div>'}${repairLine}</div></section>`;}
  function standbyHint(plan){const rows=plan?.standby||[];const labels={robot:'机器人',dog:'机器狗',drone:'无人机',person:'巡检员'};return ['robot','dog','drone','person'].map(kind=>`${labels[kind]} ${rows.filter(row=>row.type===kind).length}`).join(' · ');}
  function runningRows(){return tasks.filter(item=>['执行中','已派发','返厂中'].includes(item.status)).map(task=>`<article class="task-card" data-task-progress="${e(task.id)}"><header><div class="task-card-title">${taskMark(task)}<div><b>${e(task.name)}</b><div class="crew">${namedDeviceMarks(task.executor)||'执行中'}</div></div></div><div class="task-card-side">${badge(task.status)}${progressMeter(task)}</div></header>${schemeList(task.id)}</article>`).join('');}
  function dispatchQueue(){const pending=tasks.filter(item=>['待调度','待派发'].includes(item.status)).sort((a,b)=>Number(String(b.name).startsWith('紧急'))-Number(String(a.name).startsWith('紧急')));const current=v1Plan||previewPlan;const plans=current?.assignments||[];const blocked=Object.fromEntries((current?.blocked||[]).map(item=>[item.task_id,item.summary]));const rows=pending.map(task=>{const group=plans.filter(item=>item.task_id===task.id);const index=plans.findIndex(item=>item.task_id===task.id);const plan=group[0]||null;const raw=plan?.resolution||'';const fallback=String(raw).startsWith('兜底派出');const note=fallback?'':(raw&&!String(raw).startsWith('调度判断')?raw:(!plan?(blocked[task.id]||holdReason(task)):''));const active=plans[selectedPlanIndex]?.task_id===task.id;const action=plan?`<button class="btn primary" data-action="send-task" data-id="${e(task.id)}" data-resource="${e(group.map(item=>item.resource_id).join(','))}">${fallback?'兜底派出':'派出'} ${teamChips(group)}</button>`:`<span class="ops-hold">派不出</span>`;const listed=schemeList(task.id);const recommend=!listed&&group.length?`${fallback?'兜底派出':'系统推荐派出'}：${e(group.map(item=>item.resource_name).join('、'))}`:'';return `<div class="ops-row queue ${active?'active':''}"><button class="ops-name" data-action="preview-task" data-index="${index}">${taskMark(task)}<span><b>${e(task.name)}</b>${recommend?`<small class="ops-recommend">${recommend}</small>`:''}<small class="ops-team">${e(taskTypeNames[task.type]||'巡检')}</small>${note&&note!==recommend?`<small class="ops-fix">${e(note)}</small>`:''}</span></button>${listed}${action}</div>`;}).join('');const busy=runningRows();const title=pending.length?'待派事件':'执行中';const hint=pending.length?`${pending.length} · 可派 ${standbyHint(current)}`:`${tasks.filter(item=>['执行中','已派发','返厂中'].includes(item.status)).length}`;return `<section class="card ops-card dispatch-priority"><div class="card-head"><h2>${title}</h2><span class="hint">${hint}</span></div><div class="ops-list">${busy}${rows||(busy?'':'<div class="empty-state">暂无待派事件</div>')}</div></section>`;}
  function assignmentPanel(assignment){if(!assignment)return '<div class="empty-state">暂无方案</div>';const audit=(v1Plan?.audit||[]).filter(row=>row.task_id===assignment.task_id).sort((a,b)=>Number(b.accepted)-Number(a.accepted)||b.score-a.score).slice(0,8);const quote=assignment.bid_quote||{};return `<div class="planner-detail-grid"><div><div class="route-sequence"><small>巡检顺序</small><b>设备位置 → 任务起点 → ${(assignment.route.waypoint_order||[]).map(e).join(' → ')} → 返回点</b></div></div><div class="decision-ledger"><div class="ledger-head"><span>最低综合报价</span><b>${e(assignment.resource_name)}</b><strong>${e(quote.total_cost??assignment.score)} 分</strong></div><div class="decision-metrics"><span><small>用时</small><b>${Math.round((quote.time_s||0)/60)} 分</b></span><span><small>电耗</small><b>${e(quote.energy_kwh??'—')} 度</b></span><span><small>风险</small><b>${e(quote.risk??'—')}</b></span></div><ol class="reason-list">${(assignment.reasons||[]).map(reason=>`<li>${e(reason)}</li>`).join('')}</ol></div></div><div class="candidate-audit"><div class="card-head"><h2>候选报价</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>候选设备</th><th>状态</th><th>得分</th><th>电量预算</th><th>判定依据</th></tr></thead><tbody>${audit.map(row=>`<tr><td><strong>${e(row.resource_name)}</strong><div class="task-meta">${e(typeNames[row.resource_type]||row.resource_type)}</div></td><td><span class="audit-state ${row.accepted?'pass':'reject'}">${row.accepted?'通过':'拒绝'}</span></td><td>${row.accepted?`<b>${e(row.score)}</b>`:'—'}</td><td>${row.battery_after_pct==null?'—':`${e(row.battery_after_pct)}% 剩余`}</td><td>${e((row.accepted?row.reasons:row.rejected_by).join('；'))}</td></tr>`).join('')}</tbody></table></div></div>`;}
  function incidentStrip(){return `<section class="card event-feed"><div class="card-head"><h2>动态</h2></div>${simulationEvents.length?simulationEvents.slice(0,6).map(item=>{const task=tasks.find(row=>row.name===item.name)||(item.kind==='紧急任务'||item.kind==='故障返厂'?{name:'紧急巡检'}:{name:item.name});return `<div class="event-feed-row">${taskMark(task)}<time>${e(new Date(item.time).toLocaleTimeString('zh-CN',{hour12:false}))}</time><b>${e(item.kind)}</b><span>${e(item.name)}</span><span class="ops-team">${namedDeviceMarks(item.device)}</span>${badge(item.status)}</div>`;}).join(''):'<div class="empty-state">暂无</div>'}</section>`;}

  function costFor(task){const estimate=(previewPlan?.assignments||[]).find(a=>a.task_id===task.id)?.cost_estimate;if(task.cost){if(['待调度','待派发'].includes(task.status)){if(estimate){const cost={...task.cost,forecast:{...task.cost.forecast}};for(const key of ['energy_kwh','distance_m','duration_seconds','ascent_m'])cost.forecast[key]+=estimate[key];return cost;}return {...task.cost,unknownForecast:true};}return task.cost;}if(!estimate)return null;return {used:{energy_kwh:0,distance_m:0,duration_seconds:0,ascent_m:0},remaining:estimate,forecast:estimate,baseline:estimate,rates:{},updated_at:new Date().toISOString(),reassignments:0};}
  function taskCostsView(){return `<section class="card cost-panel"><div class="card-head"><h2>任务成本</h2><span class="hint">已用 / 预计总量</span></div><div class="cost-scroll"><table class="data-table"><thead><tr><th>任务 / 状态</th><th>电耗 / 度</th><th>设备用时</th><th>距离 / km</th><th>爬升 / m</th><th>重调度</th></tr></thead><tbody>${tasks.map(task=>`<tr data-cost-task="${e(task.id)}"><td><strong>${e(task.name)}</strong><small class="cell-note">${e(task.status)} · ${e(task.executor||'待分配')}</small></td>${['energy_kwh','duration_seconds','distance_m','ascent_m'].map(key=>`<td class="cost-value" data-cost-key="${key}">—</td>`).join('')}<td>${costFor(task)?.reassignments||0}</td></tr>`).join('')}</tbody></table></div></section>`;}
  function updateCostNumbers(){const money=value=>`${value.toFixed(1)} 元`;let routeTotal=0;document.querySelectorAll('[data-cost-task],[data-route-cost-task]').forEach(row=>{const task=tasks.find(t=>t.id===(row.dataset.costTask||row.dataset.routeCostTask));if(!task)return;const cost=costFor(task);if(!cost)return;const elapsed=Math.max(0,(Date.now()-Date.parse(cost.updated_at))/1000);const usedValue=key=>Math.min(cost.forecast[key],cost.used[key]+(cost.rates?.[key]||0)*Math.min(6,elapsed));const fmt=v=>v==null?'—':v.toFixed(3);row.querySelectorAll('[data-cost-key]').forEach(cell=>{const key=cell.dataset.costKey;const used=usedValue(key);cell.textContent=`${key==='distance_m'?(used/1000).toFixed(2):key==='duration_seconds'?`${Math.floor(used/60)}:${String(Math.floor(used%60)).padStart(2,'0')}`:key==='energy_kwh'?fmt(used):String(Math.round(used))} / ${cost.unknownForecast?'待规划':key==='distance_m'?(cost.forecast[key]/1000).toFixed(2):key==='duration_seconds'?`${Math.floor(cost.forecast[key]/60)}:${String(Math.floor(cost.forecast[key]%60)).padStart(2,'0')}`:key==='energy_kwh'?fmt(cost.forecast[key]):String(Math.round(cost.forecast[key]))}`;});const resource=resources.find(item=>item.name===String(task.executor||'').split('、')[0]);const forecast=cost.forecast||{};const yuan=(Number(forecast.energy_kwh)||0)*.85+(Number(forecast.duration_seconds)||0)/3600*(hourRate[resource?.type]||40);if(row.dataset.routeCostTask){row.querySelector('[data-route-cost-key="distance_m"]')?.replaceChildren(document.createTextNode(`${(usedValue('distance_m')/1000).toFixed(2)} km`));row.querySelector('[data-route-cost-key="energy_kwh"]')?.replaceChildren(document.createTextNode(usedValue('energy_kwh').toFixed(3)));row.querySelector('[data-route-cost-key="duration_seconds"]')?.replaceChildren(document.createTextNode(`${Math.floor(usedValue('duration_seconds')/60)}:${String(Math.floor(usedValue('duration_seconds')%60)).padStart(2,'0')}`));row.querySelector('[data-route-cost-key="yuan"]')?.replaceChildren(document.createTextNode(money(yuan)));routeTotal+=yuan;}});const totalNode=document.querySelector('[data-route-cost-total]');if(totalNode)totalNode.textContent=`合计 ${money(routeTotal)}`;}
  function terrainView(){return `<section class="card terrain-panel"><div class="card-head"><h2>地形通行</h2><span class="hint">通行概率</span></div><table class="data-table"><thead><tr><th>地形</th><th>可通行概率</th><th>规划处理</th></tr></thead><tbody>${terrainPredictions.map(t=>`<tr><td><i class="terrain-dot" style="background:${e(t.color)}"></i>${e(t.name)}</td><td>${Number(t.probability).toFixed(2)}</td><td>${e(t.action)}</td></tr>`).join('')}</tbody></table></section>`;}
  function defectsView(){return `<section class="card defect-panel"><div class="card-head"><h2>缺陷样例</h2><span class="hint">公开数据 · 非实时推理</span></div><div class="defect-gallery"><figure><a href="/assets/defects/road-damage.jpg" target="_blank" rel="noopener"><img src="/assets/defects/road-damage.jpg" alt="真实道路裂缝与坑洼照片" loading="lazy"></a><figcaption>道路裂缝与坑洼</figcaption></figure><figure><a href="/assets/defects/example-2.png" target="_blank" rel="noopener"><img src="/assets/defects/example-2.png" alt="真实道路裂缝和坑洼样例集" loading="lazy"></a><figcaption>道路缺陷样例集</figcaption></figure></div><a class="defect-source" href="https://github.com/biankatpas/Cracks-and-Potholes-in-Road-Images-Dataset" target="_blank" rel="noopener">来源：Bianka Passos · MIT</a></section>`;}
  const hourRate={person:40,robot:48,dog:36,drone:90};
  function roadMeters(path,units=70){let meters=0;for(let i=1;i<path.length;i++)meters+=Math.hypot((path[i].x-path[i-1].x)*units,(path[i].y-path[i-1].y)*units);return meters;}
  function assignmentSpend(item){const path=(item.route?.execution_path||[]).length>1?item.route.execution_path:((item.route?.road_path||[]).length>1?item.route.road_path:(item.route?.path||[]));const distance=path.length>1?roadMeters(path,Number(item.route?.meters_per_unit)||70):(item.cost_estimate?.distance_m||0);const energy=Number(item.cost_estimate?.energy_kwh)||0;const seconds=Number(item.cost_estimate?.duration_seconds)||0;const yuan=energy*0.85+seconds/3600*(hourRate[item.resource_type]||40);return {distance,energy,seconds,yuan};}
  function routeCostBoard(){const plans=(v1Plan||previewPlan)?.assignments||[];const plannedByTask=new Map();plans.forEach(item=>{if(!plannedByTask.has(item.task_id))plannedByTask.set(item.task_id,[]);plannedByTask.get(item.task_id).push(item);});const visible=tasks.filter(task=>task.cost||['执行中','已派发','返厂中'].includes(task.status)||plannedByTask.has(task.id));const money=value=>`${value.toFixed(1)} 元`;const rows=visible.map(task=>{const cost=costFor(task);const planned=plannedByTask.get(task.id)||[];const names=task.executor||planned.map(item=>item.resource_name).join('、')||'待分配';const forecast=cost?.forecast||{};const energy=Number(forecast.energy_kwh)||0;const seconds=Number(forecast.duration_seconds)||0;const distance=Number(forecast.distance_m)||0;const resource=resources.find(item=>item.name===String(names).split('、')[0]);const yuan=energy*.85+seconds/3600*(hourRate[resource?.type]||40);const stops=task.route?.waypoint_order||planned.flatMap(item=>item.route?.waypoint_order||[]);return `<tr data-route-cost-task="${e(task.id)}"><td><strong>${e(task.name)}</strong><small class="cell-note">${e(task.status)} · ${e(stops.filter(Boolean).join(' → ')||task.route_id||'路线')}</small></td><td class="ops-team">${planned.length?teamChips(planned):e(names)}</td><td class="cost-value" data-route-cost-key="distance_m">${(distance/1000).toFixed(2)} km</td><td class="cost-value" data-route-cost-key="energy_kwh">${energy.toFixed(3)}</td><td class="cost-value" data-route-cost-key="duration_seconds">${Math.floor(seconds/60)}:${String(Math.floor(seconds%60)).padStart(2,'0')}</td><td class="cost-value" data-route-cost-key="yuan">${money(yuan)}</td></tr>`;}).join('');const total=visible.reduce((sum,task)=>{const cost=costFor(task),forecast=cost?.forecast||{},resource=resources.find(item=>item.name===String(task.executor||'').split('、')[0]);return sum+(Number(forecast.energy_kwh)||0)*.85+(Number(forecast.duration_seconds)||0)/3600*(hourRate[resource?.type]||40);},0);return `<section class="card cost-panel"><div class="card-head"><h2>路线与开销</h2><span class="hint" data-route-cost-total>合计 ${money(total)}</span></div><div class="cost-scroll"><table class="data-table"><thead><tr><th>任务</th><th>设备</th><th>路程</th><th>电耗</th><th>用时</th><th>开销</th></tr></thead><tbody>${rows||'<tr><td colspan="6" class="empty-state">暂无</td></tr>'}</tbody></table></div></section>`;}
  function dispatchV1View(){const assignments=v1Plan?.assignments||[];const selected=assignments[Math.min(selectedPlanIndex,Math.max(0,assignments.length-1))];return `${dispatchQueue()}${dispatchSceneView(selected)}${routeCostBoard()}<div class="ops-board">${liveRoster()}</div>${incidentStrip()}`;}
  function settingsView(){const types=getStore('uav_device_types',['真人','机器人','机器狗','无人机']);const protocols=getStore('uav_protocols',['MQTT','HTTP/HTTPS','WebSocket','厂商私有协议']);const roles=getStore('uav_roles',['平台管理员','调度员','设备运维员','只读观察员']);return `<div class="module-grid"><section class="card module-card"><h3>设备类型</h3><div class="tag-list">${types.map(x=>`<span class="tag">${e(x)}</span>`).join('')}</div><div class="page-actions" style="margin:14px 0 0">${actionButton('添加','add-type')}</div></section><section class="card module-card"><h3>通信协议</h3><div class="tag-list">${protocols.map(x=>`<span class="tag">${e(x)}</span>`).join('')}</div><div class="page-actions" style="margin:14px 0 0">${actionButton('添加','add-protocol')}</div></section><section class="card module-card"><h3>角色</h3>${roles.map(x=>`<div class="settings-row">${e(x)}</div>`).join('')}<div class="page-actions" style="margin-top:12px">${actionButton('添加','add-role')}</div></section></div>`;}

  function showModal(title,body,onSubmit,submitLabel='保存'){const root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop"><section class="modal"><div class="modal-head">${title}<button data-close>×</button></div><form><div class="modal-body">${body}</div><div class="modal-actions"><button type="button" class="btn" data-close>取消</button><button class="btn primary" type="submit">${e(submitLabel)}</button></div></form></section></div>`;root.querySelectorAll('[data-close]').forEach(btn=>btn.onclick=()=>root.innerHTML='');root.querySelector('.modal-backdrop').onclick=event=>{if(event.target===event.currentTarget)root.innerHTML=''};root.querySelector('form').onsubmit=async event=>{event.preventDefault();await onSubmit(new FormData(event.currentTarget));};}
  function deviceForm(device={}){const body=`<div class="form-grid"><label class="form-field">设备名称<input name="name" required value="${e(device.name||'')}"></label><label class="form-field">设备编号<input name="id" required value="${e(device.id||'')}"></label><label class="form-field">设备类型<select name="type">${Object.entries(typeNames).map(([k,v])=>`<option value="${k}" ${device.type===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="form-field">厂商型号<input name="vendor" value="${e(device.vendor||'')}"></label><label class="form-field">通信协议<select name="protocol">${getStore('uav_protocols',['MQTT','HTTP/HTTPS','WebSocket','厂商私有协议']).map(x=>`<option ${device.protocol===x?'selected':''}>${e(x)}</option>`).join('')}</select></label><label class="form-field">接入方式<select name="access"><option>边缘网关</option><option>直连</option><option>厂商云</option></select></label></div>`;showModal(device.id?'编辑设备':'新增设备',body,async fd=>{const list=getStore('uav_extra_devices',[]);const item={id:fd.get('id'),name:fd.get('name'),type:fd.get('type'),vendor:fd.get('vendor'),protocol:fd.get('protocol'),access:fd.get('access'),station:'dispatch-pool',status:device.status||'待命',task:device.task||'待命',power:'100%'};const idx=list.findIndex(row=>row.id===item.id);if(idx>=0)list[idx]=item;else list.unshift(item);saveStore('uav_extra_devices',list);$('#modalRoot').innerHTML='';await refreshData();toast('设备档案已保存');});}
  function taskForm(task){const edit=!!task;const templates={road:{label:'道路巡检',type:'robot',name:'园区道路巡检',points:'返场基地 → 主干道 A → 转角 B → 返回'},air:{label:'高空复核',type:'drone',name:'高空设施复核',points:'返场基地 → 屋顶设备 → 塔架 → 返回'},gas:{label:'气体告警',type:'robot',name:'气体浓度告警复核',points:'返场基地 → 气体告警点 → 安全通道 → 返回'},team:{label:'人工复核',type:'team',name:'现场人工复核',points:'返场基地 → 检查点 → 返回'}};const templateCards=Object.entries(templates).map(([key,item])=>`<button type="button" class="task-blueprint" data-task-template="${key}"><b>${item.label}</b><small>${taskTypeNames[item.type]}</small></button>`).join('');const body=`<section class="task-studio"><header><span>任务编排</span><small>模板会填入检查点；保存后由调度页按实时电量、天气和路网重新计算。</small></header><div class="task-blueprints">${templateCards}</div><div class="task-studio-grid"><div class="task-draft"><label class="form-field">任务名称<input name="name" required value="${e(task?.name||'巡检')}"></label><div class="task-controls"><label class="form-field">执行方式<select name="type"><option value="team" ${task?.type==='team'?'selected':''}>人工巡检</option><option value="robot" ${task?.type==='robot'?'selected':''}>地面设备</option><option value="drone" ${task?.type==='drone'?'selected':''}>无人机</option></select></label><label class="form-field">计划时间<input name="time" type="datetime-local" value="${e(task?.time||'')}"></label></div><label class="form-field">检查点<textarea name="points" rows="3" placeholder="用 → 或换行分隔检查点">${e(task?.points||'')}</textarea></label><div class="task-map-picker" data-task-map><span>在此拖拽框选巡检范围</span><i></i></div></div><aside class="task-advice" data-task-advice></aside></div></section>`;showModal(edit?'编辑任务':'新建任务',body,async fd=>{if(edit){const overrides=getStore('uav_task_overrides',{});overrides[task.id]={...task,name:fd.get('name'),type:fd.get('type'),time:fd.get('time'),points:fd.get('points')};saveStore('uav_task_overrides',overrides);$('#modalRoot').innerHTML='';await refreshData();toast('任务信息已更新');}else{try{await api('/api/tasks',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:fd.get('name'),type:fd.get('type'),station:'dispatch-pool',executor:'',time:fd.get('time'),points:fd.get('points')})});$('#modalRoot').innerHTML='';await refreshData();toast('任务已创建，等待调度');}catch(error){toast(error.message);}}},edit?'保存修改':'创建并进入调度');const root=$('#modalRoot'),type=root.querySelector('[name=type]'),advice=root.querySelector('[data-task-advice]'),picker=root.querySelector('[data-task-map]'),points=root.querySelector('[name=points]');let anchor=null;const update=()=>{const selected=type.value,deviceType=selected==='team'?'person':selected,ready=resources.filter(item=>item.type===deviceType&&['待命','在线'].includes(item.status)).sort((a,b)=>(b.power_percent||0)-(a.power_percent||0)),best=ready[0],weather=environment.weather||{},flight=selected!=='drone'||(environment.flight_allowed&&Number(weather.wind_mps||0)<=8&&Number(weather.precipitation_mm||0)===0);advice.innerHTML=`<span>调度预检</span><b>${flight&&best?'可进入调度':'需人工处理'}</b><div>候选设备：${best?`${e(best.name)} · ${best.power_percent==null?'—':`${e(best.power_percent)}%`}`:'暂无可用设备'}</div><div>${selected==='drone'?`风速 ${e(weather.wind_mps??'—')} m/s · ${flight?'允许飞行':'不建议起飞'}`:'路线将在路网可达性检查后生成'}</div><small>Jev 决策模型：预留接口，当前使用规则竞价。</small>`;};picker.onpointerdown=event=>{const r=picker.getBoundingClientRect();anchor={x:event.clientX-r.left,y:event.clientY-r.top};picker.setPointerCapture(event.pointerId);};picker.onpointerup=event=>{if(!anchor)return;const r=picker.getBoundingClientRect(),x=Math.min(anchor.x,event.clientX-r.left),y=Math.min(anchor.y,event.clientY-r.top),w=Math.abs(event.clientX-r.left-anchor.x),h=Math.abs(event.clientY-r.top-anchor.y);const box=picker.querySelector('i');box.style.cssText=`left:${x}px;top:${y}px;width:${w}px;height:${h}px`;points.value=`框选巡检范围：X ${Math.round(x/r.width*100)}–${Math.round((x+w)/r.width*100)}，Y ${Math.round(y/r.height*100)}–${Math.round((y+h)/r.height*100)}`;anchor=null;};root.querySelectorAll('[data-task-template]').forEach(button=>button.onclick=()=>{const item=templates[button.dataset.taskTemplate];root.querySelector('[name=name]').value=item.name;type.value=item.type;points.value=item.points;update();});type.onchange=update;update();}
  function deviceDetail(d){if(!d)return;const pos=d.position||{};const isNavi=String(d.vendor||'').includes('浙江人形');const motion=d.motion||{};const nominal=motion.nominal_speed_mps||d.speed_mps||0;const source=isNavi?'Navi ROS1 SDK 接口参考':'平台仿真遥测';const topics=isNavi?[[telemetryContract.odom||'/zj_humanoid/chassis/odom_info','里程计'],[telemetryContract.state||'/zj_humanoid/chassis/agv_state','底盘状态'],[telemetryContract.soc||'/zj_humanoid/chassis/charge_state','充电状态'],[telemetryContract.motor||'/zj_humanoid/chassis/motor_info','电机状态'],[telemetryContract.navigation||'/zj_humanoid/navigation/navigation_status','导航状态']]:[['position','空间位置'],['power_percent','电量'],['signal_percent','链路质量']];const body=`<section class="device-console"><header><span>${e(source)}</span><b>${e(d.name)}</b><small>${e(d.id)} · ${e(d.vendor||typeNames[d.type])}</small></header><div class="device-kpis"><div><small>状态</small><b>${e(d.status)}</b></div><div><small>电量</small><b>${d.power_percent==null?'—':`${e(d.power_percent)}%`}</b></div><div><small>巡航速度</small><b>${Number(nominal).toFixed(1)} m/s</b></div><div><small>信号</small><b>${e(d.signal_percent??'—')}%</b></div></div><div class="device-console-grid"><section><h3>运行参数</h3><dl><div><dt>位置</dt><dd>X ${Math.round((pos.x||0)*35)} · Y ${Math.round((pos.y||0)*35)} · Z ${e(pos.z??'—')} m</dd></div><div><dt>当前任务</dt><dd>${e(d.task||'待命')}</dd></div><div><dt>通行边界</dt><dd>坡度 ≤ ${e(d.max_slope_deg??'—')}° · 宽度 ≥ ${e(d.min_width_m??'—')} m</dd></div><div><dt>动画倍率</dt><dd>${motion.simulation_speed_multiplier||d.simulation_speed_multiplier||12}×（实速模型）</dd></div></dl></section><section><h3>${isNavi?'ROS 接口':'遥测字段'}</h3><ul>${topics.map(([topic,label])=>`<li><code>${e(topic)}</code><span>${e(label)}</span></li>`).join('')}</ul></section></div><footer>位置、电量、链路为仿真值；接口名称来自公开 SDK，不代表已连接真实设备。</footer></section>`;showModal('设备参数',body,async()=>{$('#modalRoot').innerHTML='';},'关闭');}
  function feedbackForm(){if(!tasks.length){toast('请先创建任务');return;}const body=`<div class="form-grid"><label class="form-field wide">关联任务<select name="task_id">${tasks.map(task=>`<option value="${e(task.id)}">${e(task.name)} · ${e(task.route_id||'任务')}</option>`).join('')}</select></label><label class="form-field">反馈类型<select name="kind"><option>完成反馈</option><option>异常反馈</option></select></label><label class="form-field wide">反馈内容<textarea name="message" rows="4" required placeholder="描述任务完成情况或发现的问题"></textarea></label></div>`;showModal('提交运行反馈',body,async fd=>{try{await api('/api/feedback',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({task_id:fd.get('task_id'),kind:fd.get('kind'),message:fd.get('message')})});$('#modalRoot').innerHTML='';await refreshData();toast('反馈已提交');}catch(error){toast(error.message);}});}
  function detailTask(task){selectedTask=task;$('#pageContent').innerHTML=`<div class="page-actions" style="margin:0 0 12px">${actionButton('← 返回任务列表','back-tasks')}</div>${logitTaskBlock(task.id)}<div class="detail-grid"><section class="card"><div class="card-head"><h2>${e(task.name)}</h2><span class="right">${badge(task.status)}</span></div><div class="card-body">${[['任务类型',taskTypeNames[task.type]||'巡检'],['路线编号',task.route_id||'—'],['执行主体',task.executor||'待分配'],['计划时间',task.time||'未设置']].map(([a,b])=>`<div class="detail-line"><span>${a}</span><b>${e(b)}</b></div>`).join('')}<h3 style="font-size:11px;margin:18px 0 8px">路线点位</h3>${(task.points||'待配置').split(/[\n,，]/).map((point,index)=>`<div class="detail-line"><span>航点 ${String(index+1).padStart(2,'0')}</span><b>${e(point)}</b></div>`).join('')}</div></section><section class="card"><div class="card-head"><h2>执行信息</h2></div><div class="card-body"><div class="detail-line"><span>任务进度</span><b>${e(task.progress||'0%')}</b></div><div class="detail-line"><span>资源要求</span><b>${e(taskTypeNames[task.type]||'巡检')}</b></div><div class="page-actions" style="margin-top:16px">${actionButton('提交反馈','add-feedback')}${actionButton('设备调度','navigate-dispatch','primary')}</div></div></section></div>`;bindActions();}

  function bindActions(){
    $('#pageContent').querySelectorAll('[data-scheme-toggle]').forEach(button=>button.onclick=event=>{event.stopPropagation();const id=button.dataset.schemeToggle;if(openSchemes.has(id))openSchemes.delete(id);else openSchemes.add(id);const list=button.closest('.scheme-list');list.classList.toggle('open',openSchemes.has(id));button.setAttribute('aria-expanded',String(openSchemes.has(id)));});
    const eventTypeSelect=$('#eventType');if(eventTypeSelect)eventTypeSelect.onchange=event=>eventType=event.target.value;
    $('#pageContent').querySelectorAll('[data-task]').forEach(node=>node.onclick=()=>{const task=tasks.find(item=>item.id===node.dataset.task);if(task)detailTask(task);});
    [...$('#pageContent').querySelectorAll('[data-action]'),...$('#pageActions').querySelectorAll('[data-action]')].forEach(node=>node.onclick=async()=>{
      const action=node.dataset.action;
      if(action==='add-device')deviceForm();if(action==='add-task')taskForm();if(action==='add-feedback')feedbackForm();
      if(action==='navigate-devices')setPage('devices');if(action==='navigate-tasks')setPage('tasks');if(action==='navigate-dispatch')setPage('dispatch');if(action==='back-tasks')setPage('tasks');if(action==='clear-assignments'){try{const overrides=getStore('uav_task_overrides',{});Object.values(overrides).forEach(item=>{if(item&&typeof item==='object')for(const key of ['executor','status','dispatch_started_at','simulation_duration_seconds','progress'])delete item[key];});saveStore('uav_task_overrides',overrides);await api('/api/simulation/reset',{method:'POST'});aiPlan=null;await refreshData();toast(String.fromCharCode(0x5df2,0x6e05,0x9664,0x6d3e,0x53d1,0x8bb0,0x5f55,0x3001,0x8d44,0x6e90,0x4efb,0x52a1,0x5df2,0x53d6,0x6d88));}catch(error){toast(error.message);}}if(action==='refresh')await refreshData();
      if(action==='device-detail'){deviceDetail(resources.find(item=>item.id===node.dataset.id));}
      if(action==='device-edit'){const d=resources.find(item=>item.id===node.dataset.id);deviceForm(d);}
      if(action==='dashboard-device-filter'){dashboardDeviceType=node.dataset.type||'all';render();}
      if(action==='task-edit'){const task=tasks.find(item=>item.id===node.dataset.id);taskForm(task);}
      if(action==='add-type')simpleAdd('设备类型','uav_device_types',['真人','机器人','机器狗','无人机']);if(action==='add-protocol')simpleAdd('通信协议','uav_protocols',['MQTT','HTTP/HTTPS','WebSocket','厂商私有协议']);if(action==='add-role')simpleAdd('用户角色','uav_roles',['平台管理员','调度员','设备运维员','只读观察员']);
      if(action==='dispatch-one')dispatchFor(node);
      if(action==='v1-plan')await requestV1Plan(node);
      if(action==='scene-task'||action==='preview-task'){const index=Number(node.dataset.index);if(index>=0){v1Plan=v1Plan||previewPlan;selectedPlanIndex=index;render();}else if(action==='scene-task'){const task=tasks.find(item=>item.id===node.dataset.id);if(task)detailTask(task);}}
      if(action==='focus-device'&&spatialScene){spatialScene.selected=node.dataset.id;const select=spatialScene.host.querySelector('[data-device-select]');if(select)select.value=node.dataset.id;}
      if(action==='send-task'){node.disabled=true;const ids=String(node.dataset.resource||'').split(',').filter(Boolean);const failed=[];let sent=0;for(const resourceId of ids){try{await api('/api/dispatch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({task_id:node.dataset.id,resource_id:resourceId})});sent+=1;if(spatialScene)spatialScene.selected=resourceId;}catch(error){failed.push(error.message);}}v1Plan=null;await refreshData();toast(failed.length?`已派出 ${sent} 台，未派出：${failed.join('；')}`:(sent>1?`已派出 ${sent} 台`:'已派出'));}
      if(action==='create-emergency'){node.disabled=true;try{const task=await api('/api/simulation/emergency-task',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type:eventType||null})});if(task.dispatch&&spatialScene)spatialScene.selected=task.dispatch.resource_id;v1Plan=null;await refreshData();selectedPlanIndex=0;render();toast(`${task.name}：${task.outcome}`);}catch(error){toast(error.message);}finally{node.disabled=false;}}
      if(action==='simulate-incident'){node.disabled=true;try{const event=await api('/api/simulation/incident',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});v1Plan=null;await refreshData();selectedPlanIndex=0;render();toast(`${event.resource_name}：${event.reason}，${event.outcome}`);}catch(error){toast(error.message);}finally{node.disabled=false;}}
      if(action==='select-v1-assignment'){selectedPlanIndex=Number(node.dataset.index)||0;render();}
      if(action==='apply-v1-plan')await applyV1Plan(node);
      if(action==='ai-dispatch')await requestAiPlan(node);
      if(action==='ai-dispatch-report')await requestAiReport(node);
      if(action==='clear-ai-report'){aiReport=null;render();}
      if(action==='clear-ai-plan'){aiPlan=null;render();}
      if(action==='apply-ai-plan')await applyAiPlan(node);
      if(action==='reset-simulation'&&window.confirm('Reset the sample dispatches and reopen completed inspection tasks?')){try{await api('/api/simulation/reset',{method:'POST'});aiPlan=null;await refreshData();setPage('dispatch');toast('Demo round reset');}catch(error){toast(error.message);}}
    });
    ['deviceSearch','deviceTypeFilter','deviceStatusFilter','taskSearch','taskStatusFilter'].forEach(id=>{const el=$('#'+id);if(el)el.oninput=()=>{const tablePage=page;const search=id==='deviceSearch'||id==='taskSearch'?el.value:'';render();if(search){const again=$('#'+id);if(again){again.value=search;again.focus();again.setSelectionRange(search.length,search.length);}}};});
  }
  function simpleAdd(title,key,defaults){showModal('添加'+title,`<label class="form-field">${title}名称<input name="name" required></label>`,async fd=>{const items=getStore(key,defaults);items.push(fd.get('name').trim());saveStore(key,items);$('#modalRoot').innerHTML='';render();toast(title+'已添加');});}
  async function dispatchFor(button){const row=button.closest('tr');const resourceName=row.querySelector('strong')?.textContent;const resource=resources.find(item=>item.name===resourceName);if(!resource)return;const matching=tasks.filter(task=>task.type===taskTypeFor[resource.type]&&['待调度','待派发'].includes(task.status));if(!matching.length){toast('没有匹配的待调度任务');return;}const body=`<label class="form-field wide">选择任务<select name="task_id">${matching.map(task=>`<option value="${e(task.id)}">${e(task.name)} · ${e(task.route_id||'任务')}</option>`).join('')}</select></label>`;showModal(`分配给 ${e(resource.name)}`,body,async fd=>{try{await api('/api/dispatch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({task_id:fd.get('task_id'),resource_id:resource.id})});$('#modalRoot').innerHTML='';await refreshData();setPage('dispatch');toast('调度已提交');}catch(error){toast(error.message);}});}
  async function requestV1Plan(button){button.disabled=true;const original=button.textContent;button.textContent='正在计算…';try{v1Plan=await api('/api/planning/plan');selectedPlanIndex=0;render();toast(`已生成 ${v1Plan.assignments.length} 项可执行方案`);}catch(error){toast(error.message);}finally{const current=$('[data-action="v1-plan"]');if(current){current.disabled=false;current.textContent=v1Plan?'重新计算方案':original;}}}
  async function applyV1Plan(button){if(!v1Plan?.assignments?.length)return;button.disabled=true;button.textContent='正在执行…';const failed=[];for(const item of v1Plan.assignments){try{await api('/api/dispatch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({task_id:item.task_id,resource_id:item.resource_id})});}catch(error){failed.push(`${item.task_name}：${error.message}`);}}v1Plan=null;selectedPlanIndex=0;await refreshData();setPage('dispatch');toast(failed.length?`部分方案未执行：${failed.join('；')}`:'V1 调度方案已执行');}
  async function requestAiPlan(button){button.disabled=true;button.textContent='千问正在分析…';try{aiPlan=await api('/api/ai/dispatch-plan',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});render();if(!aiPlan.assignments.length)toast('千问未找到可执行匹配，请检查任务和资源状态');}catch(error){toast(error.message);}finally{if(page==='dispatch'){const current=$('[data-action="ai-dispatch"]');if(current){current.disabled=false;current.textContent='✦ AI 生成调度方案';}}}}
  async function requestAiReport(button){button.disabled=true;button.textContent='报告生成中…';try{aiReport=await api('/api/ai/dispatch-report',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});render();toast('千问调度报告已生成');}catch(error){toast(error.message);}finally{if(page==='dispatch'){const current=$('[data-action="ai-dispatch-report"]');if(current){current.disabled=false;current.textContent='千问调度报告';}}}}
  async function applyAiPlan(button){if(!aiPlan?.assignments?.length)return;button.disabled=true;button.textContent='正在执行…';const failed=[];for(const item of aiPlan.assignments){try{await api('/api/dispatch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({task_id:item.task_id,resource_id:item.resource_id})});}catch(error){failed.push(`${item.task_name}：${error.message}`);}}aiPlan=null;await refreshData();setPage('dispatch');toast(failed.length?`部分调度未成功：${failed.join('；')}`:'AI 调度方案已执行');}
  function bindSearchOnRender(){ }
  $('#navigation').onclick=event=>{const link=event.target.closest('[data-page]');if(link)setPage(link.dataset.page);};
  document.body.addEventListener('click',event=>{const task=event.target.closest('.task-item[data-task]');if(task&&page==='dashboard')detailTask(tasks.find(item=>item.id===task.dataset.task));});
  setInterval(()=>$('#clock').textContent=new Date().toLocaleTimeString('zh-CN',{hour12:false}),1000);$('#clock').textContent=new Date().toLocaleTimeString('zh-CN',{hour12:false});
  setInterval(updateCostNumbers,250);
  setInterval(tickLiveBoard,500);
  initTheme();
  refreshData();
  setInterval(()=>{if(document.visibilityState==='visible')refreshData();},5000);
})();













